
CREATE TABLE IF NOT EXISTS migrations (version int PRIMARY KEY);
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL CHECK(length(name) BETWEEN 2 AND 80), role text NOT NULL DEFAULT 'member' CHECK(role IN ('member','admin')), seller_type text NOT NULL DEFAULT 'individual' CHECK(seller_type IN ('individual','dealer')), bio text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE reset_tokens (token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE rate_limits (key text PRIMARY KEY, hits integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seller_id uuid NOT NULL REFERENCES users, brand text NOT NULL, model text NOT NULL, cpu text NOT NULL, ram integer NOT NULL CHECK(ram BETWEEN 1 AND 256), storage integer NOT NULL CHECK(storage BETWEEN 16 AND 16384), storage_type text NOT NULL CHECK(storage_type IN ('SSD','HDD')), gpu text NOT NULL DEFAULT 'Integrated', screen text NOT NULL, condition text NOT NULL CHECK(condition IN ('Brand new','Refurbished','Imported used','Locally used','For parts or repair')), faults text NOT NULL, description text NOT NULL, price integer NOT NULL CHECK(price BETWEEN 10000 AND 500000000), county text NOT NULL, town text NOT NULL, battery integer CHECK(battery BETWEEN 0 AND 100), warranty text NOT NULL DEFAULT 'No warranty', negotiable boolean NOT NULL DEFAULT true, delivery boolean NOT NULL DEFAULT false, ownership_declared boolean NOT NULL CHECK(ownership_declared), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','published','reserved','sold','rejected','suspended','expired','archived')), moderation_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX listings_browse ON listings(status,created_at DESC);
CREATE INDEX listings_price ON listings(status,price);
CREATE INDEX listings_seller ON listings(seller_id);
CREATE INDEX listings_search ON listings USING gin(to_tsvector('simple',brand||' '||model||' '||cpu||' '||description));
CREATE TABLE listing_private (listing_id uuid PRIMARY KEY REFERENCES listings ON DELETE CASCADE,serial_number text NOT NULL DEFAULT '');
CREATE TABLE images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listings ON DELETE CASCADE, data bytea NOT NULL, position integer NOT NULL CHECK(position BETWEEN 0 AND 9), UNIQUE(listing_id,position));
CREATE TABLE favourites (user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, listing_id uuid NOT NULL REFERENCES listings ON DELETE CASCADE, PRIMARY KEY(user_id,listing_id));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listings, buyer_id uuid NOT NULL REFERENCES users,seller_id uuid NOT NULL REFERENCES users, CHECK(buyer_id<>seller_id), UNIQUE(listing_id,buyer_id));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations, sender_id uuid NOT NULL REFERENCES users,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 3000),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations, proposer_id uuid NOT NULL REFERENCES users,amount integer NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','expired')), expires_at timestamptz NOT NULL DEFAULT now()+interval '48 hours',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,address text NOT NULL,active boolean NOT NULL DEFAULT false);
CREATE TABLE inspection_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),location_id uuid NOT NULL REFERENCES locations,starts_at timestamptz NOT NULL, UNIQUE(location_id,starts_at));
CREATE TABLE inspections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listings, requester_id uuid NOT NULL REFERENCES users,slot_id uuid NOT NULL UNIQUE REFERENCES inspection_slots,status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','confirmed','completed','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid NOT NULL REFERENCES listings,reporter_id uuid NOT NULL REFERENCES users,reason text NOT NULL CHECK(length(reason) BETWEEN 10 AND 2000),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users,body text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users,action text NOT NULL,entity_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE ROLE marketplace_app NOLOGIN;
GRANT USAGE ON SCHEMA public TO marketplace_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON listings,listing_private,images,favourites,conversations,messages,offers,inspections,reports,notifications TO marketplace_app;
GRANT SELECT ON locations,inspection_slots TO marketplace_app;
CREATE FUNCTION app_user() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE FUNCTION app_admin() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('app.role',true),'')='admin' $$;
ALTER TABLE listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY listing_read ON listings FOR SELECT USING(status='published' OR seller_id=app_user() OR app_admin());
CREATE POLICY listing_create ON listings FOR INSERT WITH CHECK(seller_id=app_user() AND status IN ('draft','pending'));
CREATE POLICY listing_change ON listings FOR UPDATE USING(seller_id=app_user() OR app_admin()) WITH CHECK(seller_id=app_user() OR app_admin());
CREATE FUNCTION guard_listing() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF current_user='marketplace_app' AND NOT app_admin() THEN
 IF NEW.seller_id<>OLD.seller_id THEN RAISE EXCEPTION 'Cannot transfer ownership'; END IF;
 IF NEW.status NOT IN ('draft','pending','sold','archived') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Moderation required'; END IF;
END IF; RETURN NEW; END $$;
CREATE TRIGGER listing_guard BEFORE UPDATE ON listings FOR EACH ROW EXECUTE FUNCTION guard_listing();
ALTER TABLE listing_private ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_owner ON listing_private USING(EXISTS(SELECT 1 FROM listings l WHERE l.id=listing_id AND l.seller_id=app_user()));
ALTER TABLE images ENABLE ROW LEVEL SECURITY;
CREATE POLICY image_read ON images FOR SELECT USING(EXISTS(SELECT 1 FROM listings l WHERE l.id=listing_id));
CREATE POLICY image_create ON images FOR INSERT WITH CHECK(EXISTS(SELECT 1 FROM listings l WHERE l.id=listing_id AND l.seller_id=app_user() AND l.status IN ('draft','pending')));
ALTER TABLE favourites ENABLE ROW LEVEL SECURITY;
CREATE POLICY favourite_owner ON favourites USING(user_id=app_user()) WITH CHECK(user_id=app_user());
ALTER TABLE conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversation_read ON conversations FOR SELECT USING(app_user() IN (buyer_id,seller_id));
CREATE POLICY conversation_create ON conversations FOR INSERT WITH CHECK(buyer_id=app_user() AND EXISTS(SELECT 1 FROM listings l WHERE l.id=listing_id AND l.seller_id=conversations.seller_id AND l.status='published'));
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_read ON messages FOR SELECT USING(EXISTS(SELECT 1 FROM conversations c WHERE c.id=conversation_id));
CREATE POLICY message_create ON messages FOR INSERT WITH CHECK(sender_id=app_user() AND EXISTS(SELECT 1 FROM conversations c WHERE c.id=conversation_id));
ALTER TABLE offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY offer_read ON offers FOR SELECT USING(EXISTS(SELECT 1 FROM conversations c WHERE c.id=conversation_id));
-- Offer mutations go through authorised, transactional service methods only.
ALTER TABLE inspections ENABLE ROW LEVEL SECURITY;
CREATE POLICY inspection_read ON inspections FOR SELECT USING(requester_id=app_user() OR app_admin());
CREATE POLICY inspection_create ON inspections FOR INSERT WITH CHECK(requester_id=app_user() AND EXISTS(SELECT 1 FROM listings WHERE id=listing_id AND status='published') AND EXISTS(SELECT 1 FROM inspection_slots s JOIN locations l ON l.id=s.location_id WHERE s.id=slot_id AND s.starts_at>now() AND l.active));
ALTER TABLE reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_read ON reports FOR SELECT USING(reporter_id=app_user() OR app_admin());
CREATE POLICY report_create ON reports FOR INSERT WITH CHECK(reporter_id=app_user());
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_read ON notifications FOR SELECT USING(user_id=app_user());
CREATE POLICY notification_update ON notifications FOR UPDATE USING(user_id=app_user()) WITH CHECK(user_id=app_user());
INSERT INTO migrations VALUES(1);
